mapper.sql:
SELECT R.CORD_SPEC BIG_ROLL_CODE, regexp_replace(listagg(CX_MACHINE_CODE, ',') WITHIN GROUP (ORDER BY CX_MACHINE_CODE, EMBRYO_CODE), '([^,]+)(,\1)+', '\1') CX_MACHINE_CODE, /*机台编号，多个机台用逗号隔开*/ ROUND(MAX(R.SIDEWALL_LENGTH * R.TIRE_FABRIC_CRAFT / #{breadth}), 6) UNIT_CONSUME, /*压延的单耗 = 裁断单耗 * 工艺 / 幅宽，多种规格取最大值 */ ROUND(SUM(R.CLASS3_PLANNED_QTY * R.SIDEWALL_LENGTH * R.TIRE_FABRIC_CRAFT / #{breadth}), 6) USE_NUM /*12点后半部件预计消耗量， 公式：（前日成型三班计划量 - 12点成型完成量) * 单耗 * 工艺 / 幅宽 */ FROM (SELECT CI.CORD_SPEC, R.EMBRYO_CODE, CASE WHEN NVL(R.CLASS3_PLANNED_QTY, 0) > NVL(F.FINISH_QTY, 0) THEN NVL(R.CLASS3_PLANNED_QTY, 0) - NVL(F.FINISH_QTY, 0) ELSE 0 END CLASS3_PLANNED_QTY, NVL(CI.SIDEWALL_LENGTH / 1000, 0) SIDEWALL_LENGTH, /*裁断单耗，单位毫米，要换算成米*/ NVL(CI.TIRE_FABRIC_CRAFT1 / 1000, 0) TIRE_FABRIC_CRAFT, /*1#胎体布工艺，单位毫米，要换算成米*/ R.CX_MACHINE_CODE FROM (SELECT R.SCHEDULE_DATE, listagg(CX_MACHINE_CODE || '$' || EMBRYO_CODE || '$' || r.BOM_DATA_VERSION, ',') WITHIN GROUP (ORDER BY CX_MACHINE_CODE, EMBRYO_CODE, r.BOM_DATA_VERSION) CX_MACHINE_CODE, R.EMBRYO_CODE, R.BOM_DATA_VERSION, SUM(R.CLASS3_PLANNED_QTY) CLASS3_PLANNED_QTY FROM T_CX_SCHEDULE_RESULT R WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' GROUP BY R.SCHEDULE_DATE, R.EMBRYO_CODE, R.BOM_DATA_VERSION) R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
LEFT JOIN T_CX_PART_FINISH_QTY F ON F.EMBRYO_CODE = R.EMBRYO_CODE AND F.DEL_FLAG = '0' AND F.STAT_DATE = R.SCHEDULE_DATE - 1 /*取上一天的完成量*/ AND F.BOM_DATA_VERSION = R.BOM_DATA_VERSION WHERE CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CRAFT1 IS NOT NULL AND REGEXP_LIKE(TRIM(CI.TIRE_FABRIC_CRAFT1), '(^[+-]?\d{0,}\.?\d{0,}$)') UNION ALL SELECT CI.CORD_SPEC, R.EMBRYO_CODE, CASE WHEN NVL(R.CLASS3_PLANNED_QTY, 0) > NVL(F.FINISH_QTY, 0) THEN NVL(R.CLASS3_PLANNED_QTY, 0) - NVL(F.FINISH_QTY, 0) ELSE 0 END CLASS3_PLANNED_QTY, NVL(CI.SIDEWALL_LENGTH / 1000, 0) SIDEWALL_LENGTH, /*裁断单耗，单位毫米，要换算成米*/ NVL(CI.TIRE_FABRIC_CRAFT2 / 1000, 0) TIRE_FABRIC_CRAFT, /*2#胎体布工艺，单位毫米，要换算成米*/ R.CX_MACHINE_CODE FROM (SELECT R.SCHEDULE_DATE, listagg(CX_MACHINE_CODE || '$' || EMBRYO_CODE || '$' || r.BOM_DATA_VERSION, ',') WITHIN GROUP (ORDER BY CX_MACHINE_CODE, EMBRYO_CODE, r.BOM_DATA_VERSION) CX_MACHINE_CODE, R.EMBRYO_CODE, R.BOM_DATA_VERSION, SUM(R.CLASS3_PLANNED_QTY) CLASS3_PLANNED_QTY FROM T_CX_SCHEDULE_RESULT R WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' GROUP BY R.SCHEDULE_DATE, R.EMBRYO_CODE, R.BOM_DATA_VERSION) R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
LEFT JOIN T_CX_PART_FINISH_QTY F ON F.EMBRYO_CODE = R.EMBRYO_CODE AND F.STAT_DATE = R.SCHEDULE_DATE - 1 /*取上一天的完成量*/ AND F.DEL_FLAG = '0' AND F.BOM_DATA_VERSION = R.BOM_DATA_VERSION WHERE CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CRAFT2 IS NOT NULL AND REGEXP_LIKE(TRIM(CI.TIRE_FABRIC_CRAFT2), '(^[+-]?\d{0,}\.?\d{0,}$)') UNION ALL SELECT CI.CORD_SPEC, R.EMBRYO_CODE, CASE WHEN NVL(R.CLASS3_PLANNED_QTY, 0) > NVL(F.FINISH_QTY, 0) THEN NVL(R.CLASS3_PLANNED_QTY, 0) - NVL(F.FINISH_QTY, 0) ELSE 0 END CLASS3_PLANNED_QTY, NVL(CI.SIDEWALL_LENGTH / 1000, 0) SIDEWALL_LENGTH, /*裁断单耗，单位毫米，要换算成米*/ NVL(CI.TIRE_FABRIC_CRAFT3 / 1000, 0) TIRE_FABRIC_CRAFT, /*3#胎体布工艺，单位毫米，要换算成米*/ R.CX_MACHINE_CODE FROM (SELECT R.SCHEDULE_DATE, listagg(CX_MACHINE_CODE || '$' || EMBRYO_CODE || '$' || r.BOM_DATA_VERSION, ',') WITHIN GROUP (ORDER BY CX_MACHINE_CODE, EMBRYO_CODE, r.BOM_DATA_VERSION) CX_MACHINE_CODE, R.EMBRYO_CODE, R.BOM_DATA_VERSION, SUM(R.CLASS3_PLANNED_QTY) CLASS3_PLANNED_QTY FROM T_CX_SCHEDULE_RESULT R WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' GROUP BY R.SCHEDULE_DATE, R.EMBRYO_CODE, R.BOM_DATA_VERSION) R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
LEFT JOIN T_CX_PART_FINISH_QTY F ON F.EMBRYO_CODE = R.EMBRYO_CODE AND F.STAT_DATE = R.SCHEDULE_DATE - 1 /*取上一天的完成量*/ AND F.DEL_FLAG = '0' AND F.BOM_DATA_VERSION = R.BOM_DATA_VERSION WHERE CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CRAFT3 IS NOT NULL AND REGEXP_LIKE(TRIM(CI.TIRE_FABRIC_CRAFT3), '(^[+-]?\d{0,}\.?\d{0,}$)')) R GROUP BY R.CORD_SPEC

mapper.select:
SELECT S.BIG_ROLL_CODE, T.CX_MACHINE_CODE, T.UNIT_CONSUME, nvl(S.STOCK_QTY, 0) TODAY_STOCK, CASE WHEN nvl(S.STOCK_QTY, 0) > nvl(T.USE_NUM, 0) THEN nvl(S.STOCK_QTY, 0) - nvl(T.USE_NUM, 0) ELSE 0 END STOCK_QTY, nvl(T.USE_NUM, 0) CX_USE_QTY FROM (
) S LEFT JOIN (
) T ON S.BIG_ROLL_CODE = T.BIG_ROLL_CODE

SELECT CI.CORD_SPEC BIG_ROLL_CODE /*帘线规格*/ FROM T_CX_SCHEDULE_RESULT R INNER JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION INNER JOIN T_XWYY_PARAMS P ON P.PARAM_CODE = 'CLOSE_OUT_SPEC_REMARK' AND P.DEL_FLAG = '0' AND P.PARAM_VALUE IS NOT NULL WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE1 IS NOT NULL
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
AND NOT EXISTS (SELECT 1 FROM T_CX_SCHEDULE_RESULT R2 LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI2 ON R2.EMBRYO_CODE = CI2.EMBRYO_CODE AND R2.BOM_DATA_VERSION = CI2.EMBRYO_VERSION WHERE R2.SCHEDULE_DATE = R.SCHEDULE_DATE AND CI2.ORIGINAL_LINE_CODE = CI.ORIGINAL_LINE_CODE AND R2.DEL_FLAG = '0' AND CI2.DEL_FLAG = '0' AND CI2.TIRE_FABRIC_CODE1 IS NOT NULL
/* 仅对投产阶段的规格排产 */ AND CI2.PRODUCTION_STAGE = '0'
AND NOT REGEXP_LIKE(NVL(R2.CLASS1_ANALYSIS, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(NVL(R2.CLASS1_ANALYSIS_INPUT, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(NVL(R2.CLASS2_ANALYSIS, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(NVL(R2.CLASS2_ANALYSIS_INPUT, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(NVL(R2.CLASS3_ANALYSIS, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(NVL(R2.CLASS3_ANALYSIS_INPUT, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(NVL(R2.CLASS4_ANALYSIS, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(NVL(R2.CLASS4_ANALYSIS_INPUT, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(NVL(R2.CLASS5_ANALYSIS, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(NVL(R2.CLASS5_ANALYSIS_INPUT, ' '), P.PARAM_VALUE)) GROUP BY CI.CORD_SPEC
